async function evaluate(ctx: RuleContext<'P-29'>): Promise<RuleResult> {
  const event = await ctx.db.massIDEvent.findById(ctx.input.pickupEventId);
  if (!event) {
    return ctx.fail({ ruleId: 'P-29', severity: 'BLOCK',
      message: 'Pickup event not found', field: 'pickupEventId' });
  }
  if (event.lat == null || event.lon == null) {
    return ctx.fail({ ruleId: 'P-29', severity: 'BLOCK',
      message: 'GPS coordinates missing on pickup event', field: 'lat' });
  }
  const precision = ctx.geo.getPrecision(event.lat, event.lon);
  if (precision > ctx.config.maxGeoPrecisionMeters) {
    return ctx.fail({ ruleId: 'P-29', severity: 'BLOCK',
      message: `GPS precision too coarse (${precision}m > ${ctx.config.maxGeoPrecisionMeters}m)`,
      field: 'lat' });
  }
  if (event.sourceType === 'business') {
    const inside = await ctx.geo.isInsideDropOff(event.lat, event.lon);
    if (!inside) {
      return ctx.fail({ ruleId: 'P-29', severity: 'BLOCK',
        message: 'Business pickup GPS outside any active DropOffPoint',
        field: 'lat' });
    }
  }
  return ctx.pass({ ruleId: 'P-29' });
}

async function evaluate(ctx: RuleContext<'P-30'>): Promise<RuleResult> {
  const massid = await ctx.db.massID.findById(ctx.input.massidId);
  const event = await ctx.db.massIDEvent.findById(massid.dropoffEventId);
  if (!event) {
    return ctx.skip({ reason: 'Dropoff event missing (delegated to P-28).' });
  }
  const recycler = await ctx.db.participant.findById(massid.recyclerId);
  if (!recycler) {
    return ctx.fail({ ruleId: 'P-30', severity: 'BLOCK',
      message: 'Recycler not found', field: 'recyclerId' });
  }
  const dropoffAddrId = event.addressId;
  const recyclerAddrId = recycler.primaryAddressId;
  if (!dropoffAddrId || !recyclerAddrId) {
    return ctx.fail({ ruleId: 'P-30', severity: 'BLOCK',
      message: 'Drop-off or recycler address missing', field: 'addressId' });
  }
  if (dropoffAddrId !== recyclerAddrId) {
    return ctx.fail({ ruleId: 'P-30', severity: 'BLOCK',
      message: `Drop-off address (${dropoffAddrId}) does not match recycler address (${recyclerAddrId})`,
      field: 'addressId' });
  }
  return ctx.pass({ ruleId: 'P-30' });
}

