async function evaluate(ctx: RuleContext<'EU-09'>): Promise<RuleResult> {
  const massid = await ctx.db.massid.findById(ctx.input.massidId);
  const wtn = await ctx.db.document.findFirst({ where: {
    massidId: massid.id,
    type: { in: ['waste_transfer_note', 'digital_equivalent'] }
  }});
  if (!wtn) return ctx.skip({ reason: 'EU-07 covers existence.' });
  const wtnParties = wtn.payload?.parties || {};
  const roles = [
    { key: 'generator', participantId: massid.generatorId },
    { key: 'hauler',    participantId: massid.haulerId },
    { key: 'recycler',  participantId: massid.recyclerId }
  ];
  const mismatches = [];
  let comparableRoles = 0;
  for (const r of roles) {
    const participant = r.participantId
      ? await ctx.db.participant.findById(r.participantId)
      : null;
    const chainFiscal   = participant?.fiscalId || null;
    const chainCompany  = participant?.companyRegistration || null;
    const wtnFiscal     = wtnParties[r.key]?.taxId || null;
    const wtnCompany    = wtnParties[r.key]?.companyRegistration || null;
    const fiscalPair    = wtnFiscal  && chainFiscal;
    const companyPair   = wtnCompany && chainCompany;
    if (!fiscalPair && !companyPair) continue; // SKIP role (delegated to EU-08)
    comparableRoles += 1;
    const fiscalMatch  = fiscalPair  ? wtnFiscal  === chainFiscal  : null;
    const companyMatch = companyPair ? wtnCompany === chainCompany : null;
    // MATCH if at least one identifier pair matches; MISMATCH only if BOTH pairs exist and BOTH diverge
    if (fiscalMatch === true || companyMatch === true) continue;
    if (fiscalMatch === false && companyMatch === false) {
      mismatches.push({ role: r.key, wtnFiscal, chainFiscal, wtnCompany, chainCompany });
    }
  }
  if (mismatches.length) {
    return ctx.fail({ ruleId: 'EU-09', severity: 'BLOCK',
      message: `WTN parties mismatch Participant chain on ${mismatches.map(m => `${m.role} (wtn taxId=${m.wtnFiscal}/reg=${m.wtnCompany} vs participant taxId=${m.chainFiscal}/reg=${m.chainCompany})`).join('; ')}`,
      field: 'parties' });
  }
  if (comparableRoles === 0) {
    return ctx.skip({ ruleId: 'EU-09', reason: 'No overlapping identifiers between WTN and chain; delegated to EU-08 for completeness.' });
  }
  return ctx.pass({ ruleId: 'EU-09' });
}

