  }
  if (!p.reachComplianceProcedureRef || String(p.reachComplianceProcedureRef).trim() === '') {
    return ctx.fail({ ruleId: 'RC-16', severity: 'BLOCK',
      message: 'reach_compliance_procedure_ref required (Category 1 mandatory)',
      field: 'reachComplianceProcedureRef' });
  }
  if (p.popComplianceFlag !== true && p.popComplianceFlag !== 'N/A') {
    return ctx.fail({ ruleId: 'RC-16', severity: 'BLOCK',
      message: 'pop_compliance_flag must be TRUE (or N/A with justification)',
      field: 'popComplianceFlag' });
  }
  if (p.popComplianceFlag === 'N/A' &&
      (!p.popComplianceJustification || String(p.popComplianceJustification).trim() === '')) {
    return ctx.fail({ ruleId: 'RC-16', severity: 'BLOCK',
      message: 'pop_compliance_flag=N/A requires popComplianceJustification',
      field: 'popComplianceJustification' });
  }
  if (p.reachNonConformityRef && !p.reachCorrectiveActionRef) {
    return ctx.fail({ ruleId: 'RC-16', severity: 'FLAG',
      message: 'REACH non-conformity registered without corrective action record',
      field: 'reachCorrectiveActionRef' });
  }
  return ctx.pass({ ruleId: 'RC-16' });
}

async function evaluate(ctx: RuleContext<'RC-17'>): Promise<RuleResult> {
  // TODO ADR-046: replace participant.type check with ctx.activeHomologation(participantId, registryId, asOf, 'RECYCLER' | 'PROCESSOR')
  const p = await ctx.db.participant.findUnique({ where: { id: ctx.input.participantId } });
  if (!p || !['R', 'P'].includes(p.type) || p.region /* TODO ADR-052/M17: source via Address.countryCode */ !== 'EU') {
    return ctx.pass(); // not applicable in this context (was ctx.skip)
  }
  const missing = [];
  if (!p.complaintsRegisterRef || String(p.complaintsRegisterRef).trim() === '') missing.push('complaintsRegisterRef');
  if (!p.complaintsProcedureRef || String(p.complaintsProcedureRef).trim() === '') missing.push('complaintsProcedureRef');
  if (missing.length > 0) {
    return ctx.fail({ ruleId: 'RC-17', severity: 'FLAG',
      message: `Complaints management docs missing: ${missing.join(', ')}`,
      field: missing[0] });
  }
  return ctx.pass({ ruleId: 'RC-17' });
}

async function evaluate(ctx: RuleContext<'PG-21'>): Promise<RuleResult> {
  const thresholds = await ctx.config.load<StorageThresholds>('storage_thresholds', 'v1');
  const inv = await ctx.db.inventory.findFirst({ where: { participantId: ctx.input.participantId }, orderBy: { snapshotDate: 'desc' } });
  const license = await ctx.db.recyclerLicense.findFirst({ where: { participantId: ctx.input.participantId, validUntil: { gte: ctx.now } } });
  if (!inv || !license) return ctx.skip({ reason: 'Inventory snapshot or storage license missing.' });
  const avg3m = (inv.stockLevelCurrentKg + inv.stockLevelM1Kg + inv.stockLevelM2Kg) / 3;
  const limit = license.licensedStorageVolumeKg;
  if (avg3m > thresholds.flag_ratio * limit) {
    return ctx.fail({ ruleId: 'PG-21', severity: 'FLAG',
      message: `3-month avg stock (${avg3m.toFixed(0)}kg) > licensed storage limit (${limit}kg)`,
      field: 'stockLevelCurrentKg',
      metadata: { avg3m, limit, ratio: avg3m / limit } });
  }
  return ctx.pass({ ruleId: 'PG-21' });
}

async function evaluate(ctx: RuleContext<'PG-22'>): Promise<RuleResult> {
  const m = ctx.massid;
  if (!m.consumerClass) {
    return ctx.fail({ ruleId: 'PG-22', severity: 'BLOCK', message: 'MassID.consumerClass must be declared at origin (INDUSTRIAL | COMMERCIAL | POST_CONSUMER | MUNICIPAL).', field: 'consumerClass' });
  }
  const o = await ctx.db.recyclingOutcome.findFirst({ where: { massidId: m.id } });
  if (!o) return ctx.skip({ reason: 'No RecyclingOutcome yet — re-evaluates on RECYCLING_OUTCOME_WRITE secondary trigger.' });
  const sum = (o.preConsumerPct || 0) + (o.postConsumerPct || 0);
  if (Math.abs(sum - (o.recycledContentPct || 0)) > 0.5) {
    return ctx.fail({ ruleId: 'PG-22', severity: 'BLOCK', message: 'Pre+post-consumer split (' + sum.toFixed(1) + '%) inconsistent with recycled_content_pct (' + (o.recycledContentPct || 0).toFixed(1) + '%). Tolerance ±0.5%.', field: 'preConsumerPct/postConsumerPct' });
  }
  // Consistency: POST_CONSUMER MassID can only fill postConsumerPct
  if (m.consumerClass === 'POST_CONSUMER' && (o.preConsumerPct || 0) > 0) {
    return ctx.fail({ ruleId: 'PG-22', severity: 'BLOCK', message: 'POST_CONSUMER origin cannot contribute to preConsumerPct.', field: 'preConsumerPct' });
  }
  if ((m.consumerClass === 'INDUSTRIAL' || m.consumerClass === 'COMMERCIAL') && (o.postConsumerPct || 0) > 0) {
    return ctx.fail({ ruleId: 'PG-22', severity: 'BLOCK', message: m.consumerClass + ' origin cannot contribute to postConsumerPct.', field: 'postConsumerPct' });
  }
  return ctx.pass({ ruleId: 'PG-22' });
}

async function evaluate(ctx: RuleContext<'PG-23'>): Promise<RuleResult> {
  const m = ctx.massid;
  if (!m.haulerId) return ctx.skip({ reason: 'MassID has no hauler — skip.' });
  const doc = await ctx.db.document.findFirst({ where: { participantId: m.haulerId, type: 'hauler_license' }, orderBy: { validUntil: 'desc' } });
  if (!doc) {
    return ctx.fail({ ruleId: 'PG-23', severity: 'BLOCK', message: 'Hauler ' + m.haulerId + ' has no hauler_license document.', field: 'hauler_license' });
  }
  if (doc.validFrom > m.pickupAt || doc.validUntil < m.pickupAt) {
    return ctx.fail({ ruleId: 'PG-23', severity: 'BLOCK', message: 'Hauler license not valid at pickupAt (validFrom=' + doc.validFrom.toISOString() + ', validUntil=' + doc.validUntil.toISOString() + ').', field: 'validUntil' });
  }
  return ctx.pass({ ruleId: 'PG-23' });
}

async function evaluate(ctx: RuleContext<'PG-24'>): Promise<RuleResult> {
  const d = ctx.document;
  if (!d.sha256Hash || !d.uploadedAt || d.version == null) {
    return ctx.fail({ ruleId: 'PG-24', severity: 'BLOCK', message: 'Document missing integrity metadata (sha256Hash / uploadedAt / version).', field: 'sha256Hash/uploadedAt/version' });
  }
  // Drift detection: re-hash current content
  const currentHash = await ctx.storage.sha256(d.storageRef);
  if (currentHash !== d.sha256Hash) {
    return ctx.fail({ ruleId: 'PG-24', severity: 'BLOCK', message: 'Document content drift detected (stored hash != current content hash). Possible tampering or storage corruption.', field: 'sha256Hash' });
  }
  return ctx.pass({ ruleId: 'PG-24' });
}

async function evaluate(ctx: RuleContext<'PG-25'>): Promise<RuleResult> {
  const policy = await ctx.config.load<RetentionPolicy>('retention_policy', 'v1');
  const violations: string[] = [];
  for (const [category, years] of Object.entries(policy.retention_periods_years)) {
    const cutoff = new Date(ctx.now);
    cutoff.setFullYear(cutoff.getFullYear() - years);
    const oldest = await ctx.db.byCategory(category).oldest();
    if (!oldest) continue;
    if (oldest.createdAt < cutoff) {
      const purgeAuth = await ctx.db.purgeAuthorization.findFirst({ where: { category, retentionExpiresAt: { lte: ctx.now } } });
      if (!purgeAuth) {
        violations.push(category + ': oldest record at ' + oldest.createdAt.toISOString() + ' exceeds ' + years + 'y retention without purge authorization');
      }
    }
  }
  if (violations.length > 0) {
    return ctx.fail({ ruleId: 'PG-25', severity: 'BLOCK', message: 'Retention violations: ' + violations.join('; '), field: 'retention_policy' });
  }
  return ctx.pass({ ruleId: 'PG-25' });
}

async function evaluate(ctx: RuleContext<'PG-26'>): Promise<RuleResult> {
  const m = ctx.massid;
  if (!m.weighEvent || !['bridge_scale', 'floor_scale', 'hopper_scale'].includes(m.weighEvent.scaleType)) {
    return ctx.skip({ reason: 'No industrial scale used — skip.' });
  }
  const cal = await ctx.db.document.findFirst({ where: { participantId: m.recyclerId, type: 'scale_calibration_certificate', scaleId: m.weighEvent.scaleId }, orderBy: { validUntil: 'desc' } });
  if (!cal) {
    return ctx.fail({ ruleId: 'PG-26', severity: 'FLAG', message: 'No scale_calibration_certificate for scale ' + m.weighEvent.scaleId + '.', field: 'calibration' });
  }
  const oneYearAgo = new Date(m.weighEvent.weighedAt);
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
  if (cal.validUntil < m.weighEvent.weighedAt || cal.issuedAt < oneYearAgo) {
    return ctx.fail({ ruleId: 'PG-26', severity: 'FLAG', message: 'Scale calibration expired or older than 12 months at weighEvent.', field: 'calibration.validUntil' });
  }
  return ctx.pass({ ruleId: 'PG-26' });
}

async function evaluate(ctx: RuleContext<'PG-27'>): Promise<RuleResult> {
  const p = ctx.participant;
  if (p.role !== 'R') return ctx.skip({ reason: 'Only Recyclers — skip.' });
  const doc = await ctx.db.document.findFirst({ where: { participantId: p.id, type: 'pellet_loss_prevention_procedure' }, orderBy: { validUntil: 'desc' } });
  if (!doc) {
    return ctx.fail({ ruleId: 'PG-27', severity: 'FLAG', message: 'Recycler has no pellet_loss_prevention_procedure document.', field: 'pelletLossProcedure' });
  }
  const oneYearAgo = new Date(ctx.now);
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);
  if (doc.validUntil < ctx.now || doc.issuedAt < oneYearAgo) {
    return ctx.fail({ ruleId: 'PG-27', severity: 'FLAG', message: 'Pellet loss procedure expired or older than 12 months.', field: 'validUntil' });
  }
  return ctx.pass({ ruleId: 'PG-27' });
}

async function evaluate(ctx: RuleContext<'PG-28'>): Promise<RuleResult> {
  const o = ctx.recyclingOutcome;
  const config = await ctx.config.load<SvhcSubstances>('svhc_substances', 'v1');
  const req = config.screening_requirements_by_end_use[o.intendedEndUse];
  if (!req || !req.screening_required) return ctx.skip({ reason: 'End use ' + o.intendedEndUse + ' does not require screening (TECHNICAL or unset).' });
  const cert = await ctx.db.document.findFirst({ where: { participantId: o.recyclerId, type: 'svhc_screening_certificate' }, orderBy: { issuedAt: 'desc' } });
  if (!cert) {
    return ctx.fail({ ruleId: 'PG-28', severity: 'FLAG', message: 'svhc_screening_certificate missing for intendedEndUse=' + o.intendedEndUse + '.', field: 'svhc_screening_certificate' });
  }
  const ageMonths = (ctx.now.getTime() - cert.issuedAt.getTime()) / (1000 * 60 * 60 * 24 * 30);
  if (ageMonths > req.renewal_months) {
    return ctx.fail({ ruleId: 'PG-28', severity: 'FLAG', message: 'Certificate aged ' + ageMonths.toFixed(1) + 'm > renewal_months=' + req.renewal_months + ' for ' + o.intendedEndUse + '.', field: 'cert.issuedAt' });
  }
  const maxPpm = req.max_svhc_ppm;
  const exceeded = (cert.testResults || []).filter((r: any) => r.measured_ppm > maxPpm);
  if (exceeded.length > 0) {
    return ctx.fail({ ruleId: 'PG-28', severity: 'FLAG', message: 'Certificate shows substances exceeding ' + maxPpm + 'ppm: ' + exceeded.map((r: any) => r.substance_id + '=' + r.measured_ppm + 'ppm').join(', ') + '.', field: 'cert.testResults' });
  }
  return ctx.pass({ ruleId: 'PG-28' });
}
